  "creator.dmHint.ai": "L'IA raconte, tranche et fait vivre le monde. Le chef du groupe la guide.",
  "creator.dmHint.steered": "L'IA raconte chaque tour. Tu es derrière l'écran avec l'intrigue, la console et le dernier mot, et tu ne joues aucun personnage.",
  "creator.dmHint.human": "Tu racontes. Le serveur fait quand même respecter chaque règle et lance chaque dé.",
  "creator.dmHint.assisted": "L'histoire t'appartient ; confie à l'IA les monstres, la prose ou une suite de tours.",
  "creator.difficulty.easy": "facile",
  "creator.difficulty.normal": "normale",
  "creator.difficulty.hard": "difficile",
  "creator.difficulty.deadly": "mortelle",
  "creator.difficultyHint.easy": "Des combats faciles et une histoire qui pardonne les erreurs. Parfait pour une première table.",
  "creator.difficultyHint.normal": "Des rencontres fidèles au livre. Un groupe imprudent peut quand même y laisser quelqu'un.",
  "creator.difficultyHint.hard": "Des combats plus corsés, moins de secondes chances, des ressources qui s'épuisent vraiment.",
  "creator.difficultyHint.deadly": "Part du principe que tu veux perdre des personnages. Prévois des replis et des remplaçants.",
  "creator.dmMode.label": "Qui mène cette table ?",
  "creator.dmRole.ai": "Tu joues un héros. L'IA est le maître du jeu.",
  "creator.dmRole.steered": "Tu diriges le narrateur IA, sans héros à toi.",
  "creator.dmRole.human": "Tu es le maître du jeu.",
  "creator.dmRole.assisted": "Tu es le maître du jeu, et l'IA t'aide.",
  "creator.dmMode.noAi": "Ce serveur n'a pas de conteur IA : un humain mène la table.",
  "creator.dmMode.unreachable":
    "Le backend IA ne répond pas pour l'instant. Tu peux quand même créer cette campagne, mais les tours IA échoueront jusqu'à ce qu'il soit de retour.",
  "creator.dmMode.steeredSeat":
    "Tu prends le siège de direction : pas de personnage ni de place dans le groupe. Tu vois l'arc, les feuilles, les blocs de stats et toute la carte, tu diriges l'IA entre les tours et tu tranches les règles contestées ; l'IA raconte chaque tour, et le chef du groupe est un joueur comme les autres.",
  "creator.dmMode.gmSeat":
    "Tu prends le siège de maître du jeu : pas de personnage, pas de place dans le groupe, et tu vois les feuilles, les blocs de stats et toute la carte. Le serveur lance quand même chaque dé et garde chaque nombre.",
  "creator.pack.label": "Monde tout prêt (facultatif)",
  "creator.pack.none": "Aucun pack (décor simple)",
  "creator.pack.noPackInfo":
    "Un monde tout prêt est une couche de peinture sur les mêmes règles du 5e. Il renomme races, classes, sorts et monstres pour épouser son décor, dit au maître du jeu comment l'endroit sonne, et fait remonter en tête de chaque liste du créateur de personnage les peuples et les vocations qui lui appartiennent. Rien n'est verrouillé : tu peux jouer un magicien dans un monde qui le nomme autrement.\n\nSans lui, tu obtiens le décor simple que ton genre implique, avec tout le catalogue proposé dans ses propres mots.",
  "creator.pack.blurb":
    "Un monde tout prêt renomme races, classes, sorts et monstres pour l'épouser, et dit au MJ comment il sonne. Chaque règle reste du 5e.",

  // Le groupe et ses règles.
  "creator.difficulty.info":
    "La difficulté est un conseil au maître du jeu, pas un multiplicateur de dégâts : chaque règle en dessous reste du 5e. Elle guide la façon dont les rencontres sont construites et la fréquence à laquelle un mauvais jet a le droit de vraiment te coûter cher.\n\n{list}\n\nLe chef du groupe peut la changer plus tard depuis les réglages de la table.",
  "creator.length.info":
    "Jusqu'où le MJ planifie l'histoire secrète : combien d'actes dure l'arc, et combien de vilains et de fils il sème au départ.\n\n**Courte** : trois actes, une aventure resserrée. Une poignée de séances.\n\n**Standard** : quatre ou cinq actes. La forme normale d'une campagne.\n\n**Épique** : six à huit actes, plusieurs fils menés de front.\n\nAucune longueur ne t'interdit rien. Joue après le final et une saga suivante prend le relais là où la première s'est achevée",
  "creator.field.players": "Joueurs",
  "creator.field.startLevel": "Niveau de départ",
  "creator.field.difficulty": "Difficulté",
  "creator.field.hpPerLevel": "Points de vie par niveau",
  "creator.hp.note": "Le niveau 1 garde toujours la plus haute face du dé de vie, plus la Constitution.",
  "creator.field.startingWealth": "Richesse de départ",
  "creator.wealth.note": "Ce qu'un nouveau héros a au départ ; l'or tiré au sort est lancé par le serveur.",
  "creator.field.rolledStats": "Caractéristiques tirées au sort",
  "creator.reroll.followServer": "Suivre la règle de relance du serveur",
  "creator.reroll.followServerWith": "Suivre la règle de relance du serveur ({rule})",
  "creator.reroll.keep": "Le premier jet demeure",
  "creator.reroll.low": "Relancer un jet totalisant moins de {total}",
  "creator.reroll.free": "Relancer autant que tu veux",
  "creator.reroll.note":
    "Pour les caractéristiques en 4d6 tirées ici : un joueur peut-il relancer les six. Le serveur les lance de toute façon. En suivant le serveur, les six d'un joueur ici sont ceux de sa bibliothèque ; une règle propre à la table donne à chaque joueur ses six ici.",
  "creator.field.dice": "Dés",
  "creator.dice.digital": "Dés virtuels seulement",
  "creator.dice.digitalHint": "Le serveur lance tout",
  "creator.dice.real": "Dés réels permis",
  "creator.dice.realHint.solo": "Lance tes dés à ta table et entre les chiffres",
  "creator.dice.realHint.party": "Les joueurs peuvent choisir de lancer à la table",
  "creator.field.length": "Longueur de la campagne",
  "creator.length.note":
    "Jusqu'où le MJ planifie l'histoire. Quelle que soit la longueur, la campagne continue si tu joues après le final : une saga suivante prend le relais là où la première s'est achevée.",

  // Le monde : les portails, le thème et la prémisse, puis les détails.
