  "workshop.hub.systemsHint": "Ne sers-toi que des outils dont ta partie a besoin ; rien ici n'a à être rempli avant de jouer. WorldForge, Cast, Région, Factions et Lore sont des vues des mêmes fiches : un changement dans l'une se voit dans toutes. Un atelier reste à toi jusqu'à ce que tu l'importes dans une campagne ; Plugin en fait un pack de monde, un seul fichier que n'importe quel serveur peut installer pour jouer une campagne dans ton univers.",
