  "admin.deviceWorldNote": "Ce monde tourne dans l'appli, qui gère elle-même son adresse, son partage et son chat vocal. Il n'y a ni mot de passe ni règle d'inscription à régler : quiconque reçoit un code de salon actif peut rejoindre, et personne d'autre ne peut créer de compte. Les réglages ici ajustent l'IA avec laquelle il joue.",
