  "admin.accounts.paidAi": "Backends IA payants",
  "admin.accounts.paidAiHint": "Payant désigne un backend de texte, d'images ou de voix sur un hôte public qui prend la clé de ce serveur (OpenAI, OpenRouter, un modèle hébergé), et le programme agent. Les backends sur cette machine ou ton réseau (llama-server, Ollama, ComfyUI, Kokoro, Whisper) restent ouverts à toutes les tables, clé ou pas. Une table qui n'a pas le droit de dépenser les payants peut apporter sa propre clé dans l'appli cliente.",
  "admin.accounts.paidEveryone": "Chaque campagne peut s'en servir",
  "admin.accounts.paidAdmins": "Seulement les campagnes menées par un administrateur",
  "admin.accounts.grace": "Délai de grâce de suppression de compte (jours)",
  "admin.accounts.graceHint": "Quand quelqu'un supprime son compte, il est déconnecté aussitôt et effacé après ce nombre de jours ; se reconnecter avant le conserve. 0 efface immédiatement. Supprimer un utilisateur depuis l'onglet Utilisateurs efface toujours aussitôt.",
  "admin.accounts.days": "jours",
  "admin.accounts.rolled": "Caractéristiques en 4d6",
  "admin.accounts.rolledHint": "Le serveur lance et garde les six totaux en 4d6 d'un joueur. Choisis s'il peut relancer : jamais, seulement quand les six totalisent moins qu'un total que tu fixes (70 par défaut ; le livre ne nomme aucune règle), ou autant de fois qu'il veut. C'est la règle en bibliothèque et à chaque table qui suit le serveur, où un joueur n'a qu'un lancer pour toutes. Une table peut fixer sa propre règle dans ses réglages et garde alors un lancer séparé par joueur ; un personnage créé là rejoint quand même la bibliothèque de son joueur comme les autres, et un personnage de bibliothèque ou un fichier amené à une table n'est confronté qu'à ce que les dés pouvaient donner.",
  "admin.accounts.rolled.first": "Le premier lancer tient",
  "admin.accounts.rolled.low": "Relancer un lancer bas",
  "admin.accounts.rolled.free": "Relancer autant de fois qu'il veut",
