  "admin.text.intro": "Le backend sur lequel tourne la campagne de chaque joueur. Une campagne peut toujours choisir son modèle, mais seules les campagnes d'un admin peuvent pointer vers une autre adresse ou une autre clé.",
  "admin.text.provider": "Fournisseur par défaut",
