  "admin.text.keyNone": "La plupart des serveurs locaux n'en demandent pas.",
  "admin.speed.label": "Vitesse de traitement",
  "admin.utility.heading": "Modèle utilitaire (facultatif)",
  "admin.utility.intro": "Un second modèle, plus petit, pour le travail mécanique : compactage de l'historique, résumés de chapitres et extraction de faits, ticks des arcs du monde, vérifications de lore, et réponses Ask. Rien de tout cela n'est de la narration, donc un petit modèle le fait bien pendant que le modèle d'histoire garde ses poids et son cache de prompt résidents. Laisse le nom du modèle vide pour désactiver, et chacun de ces appels retourne au modèle d'histoire. Si un modèle utilitaire configuré ne répond pas, le modèle d'histoire reprend le travail.",
