  "admin.addons.heading": "Addons",
  "admin.addons.intro": "Un addon est un programme qui tourne à côté de ce serveur et ajoute à ce qu'il sait faire : lire un PDF de livre de règles dans un atelier, bâtir une carte de combat avec des outils 3D, dessiner le plateau autrement. Les addons n'atteignent l'appli que par les portes qu'elle leur ouvre, et ce qu'ils fabriquent est soumis aux mêmes règles que tout le reste.",
  "admin.addons.auditNote": "Les addons de la liste ont été audités avant d'y entrer : chacun vit dans le dépôt GitHub de son auteur, et les fichiers exacts qui ont été vérifiés sont ceux que tu installes. Un addon tourne quand même comme un programme sur cet ordinateur avec les permissions de ce serveur, donc n'installe que ceux en qui tu as confiance. Chacun est éteint jusqu'à ce que tu l'actives.",
