  "admin.backup.deleteAria": "Supprimer {name}",
  "admin.usage.intro": "Jetons, images et voix sont comptés d'après ce que chaque backend déclare. « Payant » est ce qui a tourné sur la clé de ce serveur ou sur le programme agent ; « local » a tourné sur un backend à toi. Aucun prompt ni transcription n'est conservé pour cela, et aucun coût n'est estimé : applique les prix du backend que tu paies.",
