  "admin.usage.accountsNote": "Campagnes : possédées / menées / rejointes. Ce qu'une campagne dépense est compté à son chef de groupe, comme le réglage d'IA payante le décide par le chef ; le stockage est celui des personnages du compte plus les campagnes qu'il possède.",
  "admin.usage.campaignsNote": "Les jours actifs sont les jours avec au moins un tour du MJ, ce qui compte du jeu plutôt que des heures. Le stockage est celui de chaque image et fichier nommé par les lignes de la campagne, copies redimensionnées comprises.",
