  "table.settings.world.pack": "Pack de monde",
  "table.settings.world.packHint": "Choisis un univers tout prêt pour renommer races, classes, sorts et monstres à sa façon.",
  "table.settings.length.tip": "Jusqu'où le MJ prépare l'histoire à l'avance (actes, boss, quêtes annexes). Le changer en cours de campagne s'applique quand la prochaine saga est planifiée ; quelle que soit la durée, jouer après le final enchaîne avec une saga suite.",
  "table.settings.length.short": "Courte",
  "table.settings.length.standard": "Standard",
