  "table.settings.prep.blurb": "Copie cartes, PNJ, lore, rencontres et plus depuis un atelier ou une autre campagne. La source garde sa propre version ; les noms en collision sont numérotés plutôt qu'écrasés.",
  "table.settings.end.done": "Cette campagne est terminée",
  "table.settings.end.doneBody": "Les personnages venus d'une bibliothèque ont rapporté chez eux leur progression. L'histoire reste ici, à lire.",
  "table.settings.end.confirm": "Mettre fin à « {title} » pour tout le monde ? Chaque personnage venu d'une bibliothèque rapporte chez lui son niveau, son XP, son or, son équipement et ses sorts, et l'histoire reste ici à lire, mais personne ne peut continuer à jouer et le code de salle cesse de fonctionner. C'est irréversible.",
